-- ============================================================
-- MASCOTIENDAS.CL - Script SQL de productos
-- Total productos: 193 | Categorías: 38
-- ============================================================

-- ────────────────────────────────────
-- 1. TABLAS
-- ────────────────────────────────────

CREATE TABLE IF NOT EXISTS categorias (
    id          INT          NOT NULL AUTO_INCREMENT PRIMARY KEY,
    nombre      VARCHAR(255) NOT NULL,
    slug        VARCHAR(255) NOT NULL,
    UNIQUE KEY uq_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS productos (
    id                  INT           NOT NULL AUTO_INCREMENT PRIMARY KEY,
    wp_id               INT           DEFAULT NULL COMMENT 'ID original de WooCommerce',
    sku                 VARCHAR(100)  DEFAULT NULL,
    nombre              VARCHAR(500)  NOT NULL,
    descripcion_corta   TEXT          DEFAULT NULL,
    descripcion         LONGTEXT      DEFAULT NULL COMMENT 'HTML original de WooCommerce',
    precio_normal       INT           DEFAULT NULL COMMENT 'Precio en CLP sin decimales',
    precio_rebajado     INT           DEFAULT NULL,
    en_stock            TINYINT(1)    NOT NULL DEFAULT 1,
    inventario          INT           NOT NULL DEFAULT 0,
    tipo                VARCHAR(50)   NOT NULL DEFAULT 'simple',
    activo              TINYINT(1)    NOT NULL DEFAULT 1,
    creado_en           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actualizado_en      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS producto_categorias (
    producto_id   INT NOT NULL,
    categoria_id  INT NOT NULL,
    PRIMARY KEY (producto_id, categoria_id),
    FOREIGN KEY (producto_id)  REFERENCES productos(id)  ON DELETE CASCADE,
    FOREIGN KEY (categoria_id) REFERENCES categorias(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS producto_imagenes (
    id            INT           NOT NULL AUTO_INCREMENT PRIMARY KEY,
    producto_id   INT           NOT NULL,
    url           VARCHAR(1000) NOT NULL,
    posicion      TINYINT       NOT NULL DEFAULT 0 COMMENT '0 = imagen principal',
    FOREIGN KEY (producto_id) REFERENCES productos(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

