INSERT INTO productos (id, wp_id, sku, nombre, descripcion_corta, descripcion, precio_normal, precio_rebajado, en_stock, inventario, tipo) VALUES
  (1, 36, NULL, 'Dockennedy adulto 15 kgs', 'Dockennedy Adulto 15kgs es un alimento premium altamente digestible y sabroso, desarrollado para satisfacer las necesidades nutricionales de perros adultos de todas las razas y tamaños. Esta fórmula exclusiva utiliza ingredientes naturales, está enriquecida con lecitina, omega 3 y 6, y semillas de linaza para mejorar la salud inmunológica, digestiva y el aspecto general de tu mascota.\nSin colorantes ni preservantes artificiales, Dockennedy Adulto garantiza una alimentación saludable y equilibrada.\nFabricado en Canadá, ofrece calidad y pureza.\n\nDockennedy Adulto proporciona una nutrición excepcionalmente saludable y deliciosa para tu perro adulto. Con su alta digestibilidad y calidad premium, este alimento le ayudará a lucir sobresaliente, manteniendo una óptima salud y vitalidad a lo largo de su vida. No comprometas la calidad en la alimentación de tu mascota. Elige Dockennedy Adulto y ofrécele lo mejor para su bienestar y felicidad\n\n<strong>Composición:</strong>\n<ul>\n 	<li>Harina de Carne</li>\n 	<li>Maíz</li>\n 	<li>Trigo</li>\n 	<li>Arroz</li>\n 	<li>Aceite de Pollo</li>\n 	<li>Vitaminas y Minerales</li>\n</ul>\n<strong>Beneficios:</strong>\n<ul>\n 	<li>Aporta proteínas de alta calidad gracias a la Harina de Carne.</li>\n 	<li>El Maíz, el Trigo y el Arroz proporcionan carbohidratos de fácil digestión.</li>\n 	<li>El Aceite de Pollo ayuda a mantener la piel y el pelaje saludables.</li>\n 	<li>Las vitaminas y minerales contribuyen a la salud general del perro.</li>\n</ul>\n<strong>Información nutricional:</strong>\n<ul>\n 	<li>Proteína Cruda (mínimo): 22%</li>\n 	<li>Grasa Cruda (mínimo): 8%</li>\n 	<li>Humedad (máximo): 12%</li>\n 	<li>Fibra Cruda (máximo): 4%</li>\n 	<li>Energía Metabolizable (mínimo): 3.500 Kcal/Kg</li>\n</ul>', '<h1><strong>Dockennedy Adulto 15 kgs</strong></h1>\n&nbsp;\n\nDockennedy Adulto 15kgs es un alimento premium altamente digestible y sabroso, desarrollado para satisfacer las necesidades nutricionales de perros adultos de todas las razas y tamaños. Esta fórmula exclusiva utiliza ingredientes naturales, está enriquecida con lecitina, omega 3 y 6, y semillas de linaza para mejorar la salud inmunológica, digestiva y el aspecto general de tu mascota.\nSin colorantes ni preservantes artificiales, Dockennedy Adulto garantiza una alimentación saludable y equilibrada.\nFabricado en Canadá, ofrece calidad y pureza.\n\nDockennedy Adulto proporciona una nutrición excepcionalmente saludable y deliciosa para tu perro adulto. Con su alta digestibilidad y calidad premium, este alimento le ayudará a lucir sobresaliente, manteniendo una óptima salud y vitalidad a lo largo de su vida. No comprometas la calidad en la alimentación de tu mascota. Elige Dockennedy Adulto y ofrécele lo mejor para su bienestar y felicidad\n\n<strong>Composición:</strong>\n<ul>\n 	<li>Harina de Carne</li>\n 	<li>Maíz</li>\n 	<li>Trigo</li>\n 	<li>Arroz</li>\n 	<li>Aceite de Pollo</li>\n 	<li>Vitaminas y Minerales</li>\n</ul>\n<strong>Beneficios:</strong>\n<ul>\n 	<li>Aporta proteínas de alta calidad gracias a la Harina de Carne.</li>\n 	<li>El Maíz, el Trigo y el Arroz proporcionan carbohidratos de fácil digestión.</li>\n 	<li>El Aceite de Pollo ayuda a mantener la piel y el pelaje saludables.</li>\n 	<li>Las vitaminas y minerales contribuyen a la salud general del perro.</li>\n</ul>\n<strong>Información nutricional:</strong>\n<ul>\n 	<li>Proteína Cruda (mínimo): 22%</li>\n 	<li>Grasa Cruda (mínimo): 8%</li>\n 	<li>Humedad (máximo): 12%</li>\n 	<li>Fibra Cruda (máximo): 4%</li>\n 	<li>Energía Metabolizable (mínimo): 3.500 Kcal/Kg</li>\n</ul>', 42900, NULL, 0, 0, 'simple'),
  (2, 37, NULL, 'Dockennedy adulto control de peso 15 kgs', 'Alimento de alta digestibilidad, especialmente desarrollado para perros con sobrepeso y poca actividad física. Su cuidadosa formulación utiliza ingredientes naturales de excelente calidad y ingredientes clave para ayudar a tu perro a mejorar su apariencia general, así como su salud y vitalidad a lo largo de su vida. Sin colorantes ni saborizantes artificiales, este alimento garantiza una alimentación saludable y equilibrada. Fabricado en Canadá, cumple con los estándares nutricionales establecidos por la AAFCO y ofrece la calidad que tu perro merece.\n\n<strong>Composición:</strong>\n<ul>\n 	<li>Maíz</li>\n 	<li>Carne de pollo deshidratada</li>\n 	<li>Trigo integral</li>\n 	<li>Carne de cerdo deshidratada</li>\n 	<li>Grasa de pollo conservada con tocoferoles mixtos (una fuente de vitamina E)</li>\n 	<li>Pulpa de remolacha</li>\n 	<li>Cáscaras de arroz</li>\n 	<li>Digestión de hígado de pollo</li>\n 	<li>Linaza</li>\n 	<li>Sal</li>\n 	<li>Carbonato de calcio</li>\n 	<li>Tripolifosfato de sodio</li>\n 	<li>Cultivo de levadura</li>\n 	<li>Cloruro de potasio</li>\n</ul>\n<strong>Beneficios:</strong>\n<ul>\n 	<li>Ayuda a reducir la placa dental y limitar la formación de sarro gracias al tripolifosfato sódico y a las croquetas diseñadas especialmente para la higiene y salud oral.</li>\n 	<li>Los ácidos grasos omega 3 y 6 promueven la salud cardiovascular, apoyan el sistema inmunológico y mejoran la condición de la piel y el pelaje.</li>\n 	<li>La semilla de linaza, rica en omega 3, mejora la salud gastrointestinal, equilibra los niveles de azúcar en la sangre, reduce el colesterol y tiene propiedades antiinflamatorias.</li>\n 	<li>Formulado sin colorantes ni saborizantes artificiales para brindar una fórmula natural de alta calidad y palatabilidad.</li>\n</ul>\n<strong>Información nutricional:</strong>\n<ul>\n 	<li>Proteína bruta: mínimo 22%</li>\n 	<li>Grasa: mínimo 8%</li>\n 	<li>Fibra: máximo 8%</li>\n 	<li>Humedad: máximo 12%</li>\n 	<li>Omega 6: 2.1%</li>\n 	<li>Omega 3: 0.15%</li>\n</ul>', '<h1>Dockennedy Adulto Control de Peso 15 kgs</h1>\nAlimento de alta digestibilidad, especialmente desarrollado para perros con sobrepeso y poca actividad física. Su cuidadosa formulación utiliza ingredientes naturales de excelente calidad y ingredientes clave para ayudar a tu perro a mejorar su apariencia general, así como su salud y vitalidad a lo largo de su vida. Sin colorantes ni saborizantes artificiales, este alimento garantiza una alimentación saludable y equilibrada. Fabricado en Canadá, cumple con los estándares nutricionales establecidos por la AAFCO y ofrece la calidad que tu perro merece.\n\n<strong>Composición:</strong>\n<ul>\n 	<li>Maíz</li>\n 	<li>Carne de pollo deshidratada</li>\n 	<li>Trigo integral</li>\n 	<li>Carne de cerdo deshidratada</li>\n 	<li>Grasa de pollo conservada con tocoferoles mixtos (una fuente de vitamina E)</li>\n 	<li>Pulpa de remolacha</li>\n 	<li>Cáscaras de arroz</li>\n 	<li>Digestión de hígado de pollo</li>\n 	<li>Linaza</li>\n 	<li>Sal</li>\n 	<li>Carbonato de calcio</li>\n 	<li>Tripolifosfato de sodio</li>\n 	<li>Cultivo de levadura</li>\n 	<li>Cloruro de potasio</li>\n</ul>\n<strong>Beneficios:</strong>\n<ul>\n 	<li>Ayuda a reducir la placa dental y limitar la formación de sarro gracias al tripolifosfato sódico y a las croquetas diseñadas especialmente para la higiene y salud oral.</li>\n 	<li>Los ácidos grasos omega 3 y 6 promueven la salud cardiovascular, apoyan el sistema inmunológico y mejoran la condición de la piel y el pelaje.</li>\n 	<li>La semilla de linaza, rica en omega 3, mejora la salud gastrointestinal, equilibra los niveles de azúcar en la sangre, reduce el colesterol y tiene propiedades antiinflamatorias.</li>\n 	<li>Formulado sin colorantes ni saborizantes artificiales para brindar una fórmula natural de alta calidad y palatabilidad.</li>\n</ul>\n<strong>Información nutricional:</strong>\n<ul>\n 	<li>Proteína bruta: mínimo 22%</li>\n 	<li>Grasa: mínimo 8%</li>\n 	<li>Fibra: máximo 8%</li>\n 	<li>Humedad: máximo 12%</li>\n 	<li>Omega 6: 2.1%</li>\n 	<li>Omega 3: 0.15%</li>\n</ul>', 41900, NULL, 1, 0, 'simple'),
  (3, 38, NULL, 'Dockennedy breeder 15 kgs', 'Dockennedy Breeder es un alimento completo y balanceado muy digestible, diseñado para perros de todas las etapas de vida, proporciona beneficios significativos para el cuidado de la piel, el pelaje y las articulaciones, especialmente en perros de razas grandes o gigantes.\n\naltamente nutritivo para perros de todas las edades, especialmente recomendada para cachorros y adultos de razas grandes y gigantes, así como aquellos con mayor exigencia física. Su fórmula está diseñada para brindar una mayor aporte de energía y contiene glucosamina y condroitina para el cuidado y protección de huesos y articulaciones.\n\nAdemás, es rico en omega 3 y 6 para promover una piel sana y un pelaje brillante. Fabricado con ingredientes 100% naturales, sin subproductos, colorantes, saborizantes ni preservantes artificiales, Dockennedy Breeder garantiza una alimentación de calidad y bienestar para tu perro.\n\nDisfruta de la tranquilidad de ofrecer a tu compañero canino un alimento de alta calidad y beneficios específicos para su salud y vitalidad. Cuida a tu mascota con Dockennedy Breeder, elaborado con dedicación y compromiso en cada taza.\n\n<strong>Composición:</strong>\n<ul>\n 	<li>Carne de Pollo Deshidratada</li>\n 	<li>Arroz Integral</li>\n 	<li>Maíz Integral</li>\n 	<li>Carne de Cerdo Deshidratada</li>\n</ul>\n<strong>Beneficios:</strong>\n<ul>\n 	<li>Proporciona una piel y pelaje saludables.</li>\n 	<li>Fuente de energía de calidad.</li>\n 	<li>Apoya el cuidado articular.</li>\n 	<li>Favorece la digestión.</li>\n</ul>\n<strong>Información nutricional:</strong>\n<ul>\n 	<li>Proteína Cruda (mínimo): 30%</li>\n 	<li>Grasa Cruda (mínimo): 16%</li>\n 	<li>Fibra Cruda (máximo): 3.0%</li>\n 	<li>Humedad (máximo): 10%</li>\n 	<li>Omega 6 (mínimo): 3%</li>\n 	<li>Omega 3 (mínimo): 0.5%</li>\n 	<li>Clorhidrato de Glucosamina: 250 mg/Kg</li>\n 	<li>Sulfato de Condroitina: 50 mg/Kg</li>\n</ul>', '<h1>Dockennedy breeder 15 kgs</h1>\nDockennedy Breeder es un alimento completo y balanceado muy digestible, diseñado para perros de todas las etapas de vida, proporciona beneficios significativos para el cuidado de la piel, el pelaje y las articulaciones, especialmente en perros de razas grandes o gigantes.\n\naltamente nutritivo para perros de todas las edades, especialmente recomendada para cachorros y adultos de razas grandes y gigantes, así como aquellos con mayor exigencia física. Su fórmula está diseñada para brindar una mayor aporte de energía y contiene glucosamina y condroitina para el cuidado y protección de huesos y articulaciones.\n\nAdemás, es rico en omega 3 y 6 para promover una piel sana y un pelaje brillante. Fabricado con ingredientes 100% naturales, sin subproductos, colorantes, saborizantes ni preservantes artificiales, Dockennedy Breeder garantiza una alimentación de calidad y bienestar para tu perro.\n\nDisfruta de la tranquilidad de ofrecer a tu compañero canino un alimento de alta calidad y beneficios específicos para su salud y vitalidad. Cuida a tu mascota con Dockennedy Breeder, elaborado con dedicación y compromiso en cada taza.\n\n<strong>Composición:</strong>\n<ul>\n 	<li>Carne de Pollo Deshidratada</li>\n 	<li>Arroz Integral</li>\n 	<li>Maíz Integral</li>\n 	<li>Carne de Cerdo Deshidratada</li>\n 	<li>Harina de Gluten de Maíz</li>\n 	<li>Grasa de Ave (conservada con tocoferoles mixtos)</li>\n 	<li>Harina de Soya</li>\n 	<li>Avena</li>\n 	<li>Huevo Entero Deshidratado</li>\n 	<li>Semillas de Linaza</li>\n 	<li>Sabor Natural</li>\n 	<li>Pulpa de Remolacha Seca</li>\n 	<li>Aceite de Arenque (DHA)</li>\n 	<li>Sal</li>\n 	<li>Cloruro de Colina</li>\n 	<li>Cloruro de Potasio</li>\n 	<li>Suplemento de Vitamina E</li>\n 	<li>Carbonato de Calcio</li>\n 	<li>Sulfato de Zinc</li>\n 	<li>Sulfato de Hierro</li>\n 	<li>Hidrocloruro de Glucosamina</li>\n 	<li>Niacina</li>\n 	<li>Sulfato de Cobre</li>\n 	<li>Sulfato de Condroitina</li>\n 	<li>Sulfato de Manganeso</li>\n 	<li>Pantotenato de Calcio</li>\n 	<li>Riboflavina</li>\n 	<li>Mononitrato de Tiamina</li>\n 	<li>Biotina</li>\n 	<li>Suplemento de Vitamina A</li>\n 	<li>Clorhidrato de Piridoxina</li>\n 	<li>Selenito de Sodio</li>\n 	<li>Suplemento de Vitamina B12</li>\n 	<li>Yodato de Calcio</li>\n 	<li>Suplemento de Vitamina D3</li>\n 	<li>Ácido Fólico</li>\n 	<li>Complejo de Bisulfato de Sodio de Menadiona</li>\n</ul>\n<strong>Beneficios:</strong>\n<ul>\n 	<li>Proporciona una piel y pelaje saludables.</li>\n 	<li>Fuente de energía de calidad.</li>\n 	<li>Apoya el cuidado articular.</li>\n 	<li>Favorece la digestión.</li>\n</ul>\n<strong>Información nutricional:</strong>\n<ul>\n 	<li>Proteína Cruda (mínimo): 30%</li>\n 	<li>Grasa Cruda (mínimo): 16%</li>\n 	<li>Fibra Cruda (máximo): 3.0%</li>\n 	<li>Humedad (máximo): 10%</li>\n 	<li>Omega 6 (mínimo): 3%</li>\n 	<li>Omega 3 (mínimo): 0.5%</li>\n 	<li>Clorhidrato de Glucosamina: 250 mg/Kg</li>\n 	<li>Sulfato de Condroitina: 50 mg/Kg</li>\n</ul>', 49900, NULL, 1, 0, 'simple'),
  (4, 39, NULL, 'Dockennedy cachorro 15 kgs', 'Alimento premium diseñado para cachorros, hembras en gestación o lactancia. Con una cuidadosa formulación, este alimento garantiza una alta digestibilidad y palatabilidad para satisfacer las necesidades nutricionales de tu mascota en sus etapas de crecimiento y reproducción. Importado desde Canadá, ofrece calidad y confianza.\n\nOpción confiable y nutritiva para el crecimiento saludable de tu cachorro, así como para brindar el soporte necesario durante la etapa de gestación y lactancia. Fabricado con ingredientes de calidad y sin aditivos artificiales, este alimento garantiza una alimentación balanceada y de alto valor nutricional para tu mascota.\n\n<strong>Composición:</strong>\n<ul>\n 	<li>Carne de Pollo Deshidratada</li>\n 	<li>Maíz Amarillo Molido</li>\n 	<li>Salvado de Trigo</li>\n 	<li>Grasa de Ave (conservada en tocoferoles mixtos)</li>\n</ul>\n<strong>Beneficios:</strong>\n<ul>\n 	<li>Alimento completo y balanceado para cachorros, hembras en gestación o lactancia.</li>\n 	<li>Alta digestibilidad y palatabilidad.</li>\n 	<li>Cumple con los estándares nutricionales de la AAFCO.</li>\n 	<li>Ingredientes 100% naturales.</li>\n 	<li>Sin subproductos no aptos para consumo humano.</li>\n 	<li>Sin preservantes ni saborizantes artificiales.</li>\n</ul>\n<strong>Información nutricional:</strong>\n<ul>\n 	<li>Proteína Cruda (mínimo): 30%</li>\n 	<li>Grasa Cruda (mínimo): 16%</li>\n 	<li>Fibra Cruda (máximo): 3%</li>\n 	<li>Humedad (máximo): 10%</li>\n 	<li>DHA+EPA (mínimo): 0.05%</li>\n 	<li>Omega 6 (mínimo): 3%</li>\n 	<li>Omega 3 (mínimo): 0.4%</li>\n</ul>', '<h1>Dockennedy cachorro 15 kgs</h1>\nAlimento premium diseñado para cachorros, hembras en gestación o lactancia. Con una cuidadosa formulación, este alimento garantiza una alta digestibilidad y palatabilidad para satisfacer las necesidades nutricionales de tu mascota en sus etapas de crecimiento y reproducción. Importado desde Canadá, 