  (166, 1204, NULL, 'SNACK PREMIUM OREJA DE CERDO PARA PERROS', NULL, '<strong>Fuente de Proteína\n</strong>Hechos en base a proteína animal.\n\n<strong>Producto Natural\n</strong>No contiene preservantes ni colorantes.\n\n<strong>Hecho con Cerdo\n</strong>Producto elaborado con cerdo seleccionado.\n\n<strong>Libre de Granos\n</strong>No contiene maíz, trigo ni granos de ningún tipo.\n\n<strong>Indicaciones\n</strong>Indicado para perros de todas las razas y etapas de vida.\nObserve a su perro mientras consume este producto.\nMantenga siempre agua fresca y potable al alcance de su perro.\nConservar en un lugar fresco y seco.\n\n<strong>Advertencias\n</strong>No recomendable para consumo humano.\nMantenga lejos del alcance de los niños.\nProhibido su uso en la alimentación de rumiantes.\nNo corresponde a un alimento completo.', 3900, NULL, 0, 0, 'simple'),
  (167, 1206, NULL, 'FIT FÓRMULA GALLETAS GATO SALMÓN', NULL, 'Harina de trigo, Carne de cangrejo, Aceite de palma, Levadura de cerveza, Hierba gatera (Catnip), Aceite de girasol, Taurina, Glucosa, Vitamina E natural, Lecitina de soja, Bicarbonato de sodio y β-Caroteno.\n<ul>\n 	<li>Suplemento para gatos adultos y gatitos mayores de 8 semanas.</li>\n 	<li>Para gatos adultos ofrecer como máximo 15 galletas por día. Para gatitos ofrecer como máximo 5 galletas por día.</li>\n 	<li>Reduzca la comida principal en consecuencia. La cantidad diaria depende de la edad, peso y actividad de su gato.</li>\n</ul>', 2900, NULL, 0, 0, 'simple'),
  (168, 1209, NULL, 'FIT FÓRMULA SNACK GATO CRUNCHY', NULL, 'Harina de trigo, Arroz, Carne de atún, Carne de salmón, Maíz, Proteína de soya en polvo, Aceite De Pescado, Hierba gatera (Catnip), Taurina, Vitamina E, Lisina, Vitamina A y Vitamina B.\n<ul>\n 	<li>Suplemento para gatos adultos y gatitos mayores de 8 semanas.</li>\n 	<li>Para gatos adultos ofrecer como máximo 25 snacks por día. Para gatitos ofrecer como máximo 10 snacks por día.</li>\n 	<li>Reduzca la comida principal en consecuencia. La cantidad diaria depende de la edad, peso y actividad de su gato.</li>\n</ul>', 4500, NULL, 0, 0, 'simple'),
  (169, 1211, NULL, 'FIT FÓRMULA GALLETAS GATO CANGREJO', NULL, 'Harina de trigo, Carne de cangrejo, Aceite de palma, Levadura de cerveza, Hierba gatera (Catnip), Aceite de girasol, Taurina, Glucosa, Vitamina E natural, Lecitina de soja, Bicarbonato de sodio y β-Caroteno\n<ul>\n 	<li>Suplemento para gatos adultos y gatitos mayores de 8 semanas.</li>\n 	<li>Para gatos adultos ofrecer como máximo 15 galletas por día. Para gatitos ofrecer como máximo 5 galletas por día.</li>\n 	<li>Reduzca la comida principal en consecuencia. La cantidad diaria depende de la edad, peso y actividad de su gato.</li>\n</ul>\n&nbsp;', 2900, NULL, 0, 0, 'simple'),
